import sys; sys.path.insert(0,'/home/claude/ac-mdcu/parts')
from l23_common import mk, save
Q={}

mk(Q, 11, [8, 's2'],
 stem="A 50-year-old intoxicated man falls asleep in a bathtub while hot tap water at about 49°C keeps running over him. He is found 15 minutes later. Which statement about his burn is correct?",
 opts=["Depth depends on water temperature alone, so only redness results",
       "Long contact can cause full thickness despite moderate heat",
       "Water below 60°C produces only superficial partial-thickness injury",
       "Full thickness at this temperature needs more than six hours of contact",
       "Tap water below 50°C cannot injure intact adult skin"],
 interp="ชายเมาหลับในอ่างขณะน้ำร้อนราว 49 °C ไหลราดตัวนาน 15 นาที → อุณหภูมิไม่สูงมากแต่สัมผัสนานโดยถอนตัวไม่ได้ → ถามข้อความที่ถูกเรื่องความลึกของแผล ต้องใช้หลักว่าความลึกขึ้นกับคู่ของอุณหภูมิกับเวลาสัมผัส ไม่ใช่อุณหภูมิอย่างเดียว",
 why="ความลึกของแผลน้ำร้อนลวกขึ้นกับ<b>อุณหภูมิร่วมกับระยะเวลาที่สัมผัส</b> และความหนาของผิว (เด็กเล็กและผู้สูงอายุผิวบางไหม้ลึกเร็วกว่า) · ตาราง immersion time บอกเวลาที่ทำให้ไหม้<b>เต็มความหนา (full thickness)</b>: 158 °F (70 °C) <b>1 วินาที</b> · 140 °F (60 °C) 10 วินาที · 127 °F (≈53 °C) 1 นาที · <b>120 °F (≈49 °C) 10 นาที</b> — อุณหภูมิลดลงราว 20 °C แต่เวลาที่ต้องใช้ยาวขึ้นหลายร้อยเท่า และผิวเริ่มเสียหายได้ตั้งแต่ราว <b>44 °C</b> เมื่อสัมผัสนานหลายชั่วโมง · น้ำ 49 °C ราดตัว 15 นาทีจึงเกินเวลาที่ทำให้ไหม้เต็มความหนา และคนเมาหลับหรือหมดสติ<b>ถอนตัวจากความร้อนไม่ได้</b> เช่นเดียวกับเด็กเล็ก ผู้สูงอายุ ผู้ป่วยชัก อัมพาต หรือเบาหวานปลายประสาทชา · แผลกลุ่มนี้ช่วงแรกอาจดูแค่แดงหรือซีด แต่มักลึกกว่าที่เห็น ต้องประเมินความลึกซ้ำใน 48–72 ชั่วโมง · ชีทหน้า 2 <b>“ในกรณีที่อุณหภูมิที่สัมผัสไม่สูงมากก็สามารถทำให้เกิดเป็นบาดแผลไฟไหม้น้ำร้อนลวกได้ถ้าระยะเวลาที่สัมผัสนาน”</b> · สไลด์หน้า 8 ลายมือ <b>“temp ไม่สูงมาก แต่โดนนานก็ severe ได้”</b> และ <b>“นอนเปิดน้ำร้อนราดตัวตอนเมา”</b>",
 wrong={
  "A":"ช้อยนี้ตัดเวลาออกจากสมการ ซึ่งขัดกับตาราง immersion time ที่ทุกแถวเป็นคู่ของอุณหภูมิกับเวลา และขัดกับชีทที่ระบุว่าปัจจัยสำคัญที่สุดคือระยะเวลาและอุณหภูมิ · ไม่มีสถานการณ์ใดที่ความลึกของแผลน้ำร้อนขึ้นกับอุณหภูมิอย่างเดียว เพราะน้ำอุณหภูมิเดียวกันสัมผัส 1 วินาทีกับ 10 นาทีให้ความลึกต่างกันมาก",
  "C":"60 °C ไม่ใช่เส้นแบ่งความลึก — ตารางแสดง full thickness ได้ที่ราว 53–54 °C ภายใน 30–60 วินาที และที่ 49 °C ภายใน 10 นาที · ไม่มีสถานการณ์ใดที่น้ำต่ำกว่า 60 °C จำกัดได้แค่แผลตื้นเสมอ เพราะความลึกถูกกำหนดด้วยเวลาที่สัมผัสด้วย และผู้ที่ถอนตัวไม่ได้จะไหม้ลึกได้แม้อุณหภูมิต่ำกว่านี้มาก",
  "D":"ตัวเลขระดับหลายชั่วโมงเป็นของน้ำราว 44 °C ซึ่งเป็นจุดที่ผิวเพิ่งเริ่มถูกทำลาย ไม่ใช่ของ 49 °C · ไม่มีสถานการณ์ใดที่น้ำ 49 °C ต้องสัมผัสเกิน 6 ชั่วโมงจึงไหม้เต็มความหนา เพราะตารางให้เพียงราว 10 นาที และผิวเด็กหรือผู้สูงอายุที่บางกว่าใช้เวลาสั้นกว่านั้นอีก",
  "E":"ผิวเริ่มเสียหายจากความร้อนตั้งแต่ราว 44 °C เมื่อสัมผัสนานพอ และตารางให้ 49 °C ไหม้เต็มความหนาได้ใน 10 นาที · ไม่มีสถานการณ์ใดที่ 50 °C เป็นเส้นแบ่งว่าน้ำทำให้ผิวไหม้ได้หรือไม่ เพราะความเสียหายเป็นเส้นต่อเนื่องของอุณหภูมิกับเวลา ไม่มีจุดตัดที่ปลอดภัยแน่นอน"},
 trap="49 °C ฟังดูแค่ “ร้อนมาก” และใกล้อุณหภูมิที่แนะนำให้ตั้งเครื่องทำน้ำอุ่น จึงชวนให้เลือก D หรือ E — ตัวแยกคือเวลา: คนเมา หมดสติ หรือถอนตัวไม่ได้จะสัมผัสนานเกิน 10 นาที แผลจึงลึกเต็มความหนาได้แม้น้ำไม่ร้อนจัด",
 summary=["ความลึก = อุณหภูมิ × เวลาสัมผัส (+ ความหนาของผิว) · อุณหภูมิไม่สูงแต่สัมผัสนานก็ไหม้เต็มความหนาได้",
  "ตาราง immersion time: 158 °F 1 วินาที · 150 °F 2 วินาที · 140 °F 10 วินาที · 130 °F 30 วินาที · 127 °F 1 นาที · 120 °F 10 นาที",
  "ชีทหน้า 2: สัมผัสอุณหภูมิสูงกว่า 70 °C ไหม้ได้ในเพียง 1 วินาที",
  "ผิวเริ่มถูกทำลายราว 44 °C เมื่อสัมผัสนานหลายชั่วโมง — ไม่มีอุณหภูมิน้ำร้อนที่ปลอดภัยแน่นอน",
  "กลุ่มเสี่ยงที่ถอนตัวจากความร้อนไม่ได้: คนเมา หมดสติ ชัก เด็กเล็ก ผู้สูงอายุ อัมพาต เบาหวานเท้าชา",
  "ตัวอย่างในลายมือ: ถุงก๋วยเตี๋ยวร้อนแนบขานาน ๆ · นอนเปิดน้ำร้อนราดตัวตอนเมา",
  "แผลจากความร้อนไม่สูงแต่นานมักลึกกว่าที่เห็นตอนแรก → ประเมินความลึกซ้ำใน 48–72 ชั่วโมง"],
 opinion="เห็นด้วยกับคำตอบ B ความมั่นใจสูง — ตาราง immersion time สไลด์หน้า 8 ให้ 120 °F (≈49 °C) ไหม้เต็มความหนาใน 10 นาที และชีทหน้า 2 ยืนยันหลักอุณหภูมิไม่สูงแต่นานก็ไหม้ได้ · จุดที่ควรทราบ: สไลด์อ้างแหล่งว่า Pediatrics 62:4 ปี 1987 แต่บทความของ Feldman และคณะตีพิมพ์จริงปี 1978 (เล่ม 62) · ตัวเลขในตารางอิงงานทดลองกับผิวผู้ใหญ่ของ Moritz และ Henriques (1947) ผิวเด็กและผู้สูงอายุที่บางกว่าจึงไหม้ลึกเร็วกว่านี้ เป็นเหตุที่แนะนำตั้งเครื่องทำน้ำอุ่นไม่เกินราว 49 °C ร่วมกับเฝ้าดูเด็กขณะอาบน้ำเสมอ",
 mnemonic="<b>“ร้อนน้อยแต่นาน = ลึกได้ · 120 °F 10 นาที, 158 °F 1 วินาที”</b>",
 guide="Feldman KW, Schaller RT, Feldman JA, McMillon M. Tap water scald burns in children (Pediatrics 1978;62:1–7); Moritz AR, Henriques FC. Studies of thermal injury II (Am J Pathol 1947;23:695–720); Herndon DN. Total Burn Care 5th ed. (2018)",
 variants=["เด็ก 2 ขวบมีแผลน้ำร้อนลวกขอบเรียบรอบเท้าสองข้างเหมือนใส่ถุงเท้า เว้นรอยพับข้อ ไม่มีรอยน้ำกระเซ็น → immersion burn สงสัยถูกทำร้าย รับไว้และแจ้งทีมคุ้มครองเด็ก",
  "ชายเบาหวานเท้าชาแช่เท้าในน้ำที่รู้สึกแค่อุ่นนาน 30 นาที เกิดตุ่มน้ำและผิวซีด → ไหม้ลึกเพราะรับรู้ความร้อนไม่ได้จึงสัมผัสนาน",
  "หญิงสูงอายุอัมพาตครึ่งซีกวางกระเป๋าน้ำร้อนแนบต้นขาทั้งคืน → แผลจากความร้อนต่ำแต่นาน มักลึกกว่าที่เห็น นัดประเมินความลึกซ้ำ",
  "พ่อครัวโดนน้ำมันทอดร้อนราว 180 °C กระเด็นใส่แขนชั่วพริบตา → ไหม้ลึกได้ทันทีเพราะอุณหภูมิเกิน 70 °C ใช้เวลาไม่ถึง 1 วินาที"])

mk(Q, 12, [9, 38, 's3'],
 stem="A 24-year-old woman has a scald on her forearm. Biopsy shows loss of the epidermis and most of the dermis, but the deepest dermis with hair follicles and sweat glands remains. How is this burn classified?",
 opts=["First-degree burn limited to the epidermis",
       "Deep partial-thickness burn",
       "Superficial partial-thickness burn",
       "Fourth-degree burn involving muscle",
       "Full-thickness burn with surviving adnexa"],
 interp="แผลน้ำร้อนที่แขน biopsy เห็น epidermis และ dermis ส่วนใหญ่หาย แต่ dermis ชั้นลึกสุดที่มีรูขุมขนและต่อมเหงื่อยังเหลือ → ถามการจัดระดับความลึก ต้องใช้หลักว่า dermis เหลือ = partial thickness และเหลือแค่ชั้นลึก = ชนิดลึก",
 why="การจัดระดับความลึกยึด<b>ว่า dermis ยังเหลือหรือไม่</b>: ถ้า<b>เหลือบางส่วน = partial thickness (2°)</b> ถ้า<b>หายทั้งชั้น = full thickness (3°)</b> · partial thickness แบ่งย่อยตามความลึก: <b>superficial 2°</b> เสีย epidermis กับ papillary dermis เกิดตุ่มน้ำใส พื้นชมพูชื้น ปวดมาก หายใน 10–14 วัน · <b>deep 2°</b> ลึกถึง reticular dermis เหลือเพียงส่วนลึก ผิวขาวซีดแต่ยังนิ่ม capillary refill ช้าหรือไม่มี รับรู้แค่แรงกด หายช้า 3–4 สัปดาห์และเกิดแผลเป็นมาก · biopsy ในโจทย์เหลือ deep dermis พร้อมรูขุมขนและต่อมเหงื่อ จึงยังมีแหล่ง keratinocyte งอกผิว = <b>deep partial thickness</b> · แผลที่คาดว่าหายเกิน 2–3 สัปดาห์แบบนี้ แนวปัจจุบันมักแนะนำ<b>ตัดเนื้อตายและปลูกผิว</b>เพื่อลดแผลเป็นนูนและการหดรั้ง · ชีทหน้า 3 <b>“ระดับที่ 2 ลึก (deep 2<sup>0</sup> burns) … ชั้นบนและชั้นลึกของผิวหนังชั้นล่างแต่ยังมีบางส่วนเหลืออยู่ (deep part of dermis)”</b> · สไลด์หน้า 9 ลายมือ <b>“burn ที่มี dermis เหลือ = partial-thickness / 2<sup>nd</sup> degree burn”</b>",
 wrong={
  "A":"1° เสียหายจำกัดใน epidermis ผิวแดง แห้ง ไม่มีตุ่มน้ำ หายเองไม่เป็นแผลเป็น — biopsy ในโจทย์ลึกถึง dermis ส่วนใหญ่ จึงลึกกว่ามาก · จะถูกถ้าหญิงตากแดดทั้งวันมีผิวแดงแสบที่ไหล่ และ biopsy เห็น keratinocyte ตายเฉพาะใน epidermis โดย dermis ปกติทั้งชั้น",
  "C":"superficial 2° เสียแค่ epidermis และ papillary dermis ชั้นบน dermis ส่วนใหญ่ยังอยู่ จึงมีตุ่มน้ำใส พื้นชมพูชื้น ปวดมาก และหายใน 10–14 วัน — โจทย์เสีย dermis ไปเกือบหมด · จะถูกถ้าชายโดนน้ำร้อนลวกที่หลังมือ เกิดตุ่มน้ำใส ปวดมาก และ biopsy พบความเสียหายถึงแค่ papillary dermis",
  "D":"4° คือความเสียหายลึกผ่านผิวหนังทั้งหมดลงถึงกล้ามเนื้อ เอ็น หรือกระดูก ตรงกับป้าย Muscle · Bone บนแผนภาพ — แผลในโจทย์ยังไม่หมด dermis ด้วยซ้ำ · จะถูกถ้าช่างไฟฟ้าโดนไฟฟ้าแรงสูงที่แขน และขณะผ่าตัดพบกล้ามเนื้อปลายแขนไหม้เป็นสีเทาซีด กระตุ้นแล้วไม่หดตัว",
  "E":"full thickness หมายถึง dermis ถูกทำลายทั้งชั้นรวมทั้ง adnexa ที่ฝังอยู่ใน dermis จึงไม่เหลือแหล่งงอกผิวจากก้นแผล · ไม่มีสถานการณ์ใดที่การจัดระดับเรียกแผลที่ยังมี adnexa รอดอยู่ในก้นแผลว่า full thickness เพราะ adnexa ที่เหลือแปลว่ายังมี dermis เหลือ ตามนิยามคือ partial thickness"},
 trap="แผลลึกถึง dermis ส่วนใหญ่ฟังดูเหมือน full thickness และช้อย E ใส่คำว่า adnexa ให้ดูตรงกับ biopsy — ตัวตัดสินคือ dermis ยังเหลือหรือไม่ ไม่ใช่ลึกแค่ไหน เหลือแม้ชั้นบาง ๆ ที่มีรูขุมขน = partial thickness ชนิดลึก",
 summary=["ตัวตัดสิน: dermis เหลือ = partial thickness (2°) · dermis หายหมด = full thickness (3°)",
  "1° (epidermis): แดง แห้ง ไม่มีตุ่มน้ำ · หายเองไม่มีแผลเป็น",
  "2° ตื้น (epidermis + dermis ส่วนบน): ตุ่มน้ำใส ปวด · หาย 10–14 วัน แผลเป็นค่อนข้างดี",
  "2° ลึก (ถึง dermis ส่วนลึกแต่ยังเหลือ): ขาวซีดแต่นิ่ม · หาย 3–4 สัปดาห์ แผลเป็นมาก",
  "3° (ผิวหนังทุกชั้น ± ลึกกว่า): ขาวหรือน้ำตาล แข็งเหมือนหนัง อาจเห็นเส้นเลือดอุดตัน · หายโดยหดรั้งหรือปลูกผิว",
  "แผนภาพหน้า 9: 4° = Muscle · Bone · แผลที่คาดว่าหายเกิน 3 สัปดาห์ → พิจารณาตัดเนื้อตายและปลูกผิว"],
 opinion="เห็นด้วยกับคำตอบ B ความมั่นใจสูง — ลายมือสไลด์หน้า 9 และ 38 ใช้ dermis เหลือหรือไม่เป็นตัวแบ่ง และชีทหน้า 3 นิยาม 2° ลึกว่ายังเหลือ deep part of dermis ตรงกับ biopsy · จุดที่ต่างจากศัพท์ปัจจุบัน: ตารางในชีทหน้า 3 จัดระดับที่ 1 ไว้ใต้หัว Partial Thickness Burns ขณะที่ ABA และ ISBI ปัจจุบันเรียก 1° ว่า superficial (epidermal) burn แยกจาก partial thickness · ทางคลินิกการแยก superficial กับ deep partial ทำได้ยาก มักต้องประเมินซ้ำใน 48–72 ชั่วโมงหรือใช้ laser Doppler imaging ช่วย",
 mnemonic="<b>“เหลือ dermis = Partial · หมด dermis = Full”</b>",
 guide="ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021); Herndon DN. Total Burn Care 5th ed. (2018) — Evaluation of the burn wound; American Burn Association. Advanced Burn Life Support Provider Manual (2018 update)",
 variants=["เด็กน้ำร้อนลวกที่แขน วันแรกเป็นตุ่มน้ำพื้นชมพู วันที่ 3 พื้นแผลซีดลงและ capillary refill ช้า → แผลลึกขึ้นจาก zone of stasis ที่ตายเพิ่ม ต้องประเมินความลึกใหม่",
  "แผล deep partial thickness ที่ไหล่ถึงวันที่ 21 ยังไม่ปิด → ตัดเนื้อตายและปลูกผิว เพื่อลด hypertrophic scar และการหดรั้ง",
  "แผลน้ำร้อนลวกที่ก้ำกึ่งระหว่าง superficial กับ deep partial thickness → laser Doppler imaging ช่วง 48 ชั่วโมงถึง 5 วัน ช่วยทำนายว่าแผลจะหายเองใน 21 วันหรือไม่"])

mk(Q, 13, [9, 38, 's3'],
 stem="A 45-year-old man has a burn on his leg that is white, leathery and insensate to pinprick, with thrombosed veins visible through it. Biopsy shows destruction of the whole dermis but not the muscle. What is the depth?",
 opts=["Deep partial-thickness burn",
       "Full-thickness burn",
       "Superficial partial-thickness burn",
       "Fourth-degree burn",
       "First-degree burn"],
 interp="แผลที่ขาขาว แข็งเหมือนหนัง เข็มจิ้มไม่รู้สึก เห็นเส้นเลือดอุดตันใต้แผล biopsy dermis ถูกทำลายทั้งชั้นแต่ไม่ถึงกล้ามเนื้อ → ถามระดับความลึก ต้องใช้หลักว่า dermis หายหมด = full thickness และความปวดสวนทางกับความลึก",
 why="เมื่อ<b>dermis ถูกทำลายทั้งชั้น</b> แผลเป็น<b>full thickness (3°)</b>: collagen ที่ถูกความร้อนเสียสภาพกลายเป็น <b>eschar</b> สีขาว น้ำตาล หรือดำ <b>แข็งเหมือนหนัง</b> กดไม่ซีด ไม่มี capillary refill อาจเห็น<b>เส้นเลือดใต้ผิวอุดตัน</b>เป็นลายสีเข้ม และ<b>ไม่รู้สึกเจ็บต่อเข็ม</b>เพราะปลายประสาทใน dermis ตายไปด้วย — ความปวดจึงสวนทางกับความลึก (แผลตื้นปวดมาก แผลลึกชา) · ยังไม่ถึงกล้ามเนื้อจึงยังไม่ใช่ 4° · ไม่มี appendage เหลือ ก้นแผลงอกผิวเองไม่ได้ ต้องหายจากขอบร่วมกับการหดรั้ง แผลที่ไม่เล็กมากจึงต้อง<b>ตัดเนื้อตายและปลูกผิว</b> และถ้า eschar อยู่รอบวงแขนขาหรือหน้าอก ต้องเฝ้าระวังเลือดไปเลี้ยงส่วนปลายและการหายใจ จนอาจต้องทำ escharotomy · ชีทหน้า 3 <b>“ระดับที่ 3 — ผิวหนังทุกชั้นถูกทำลายทั้งหมด … ผิวหนังเป็นสีขาว หรือน้ำตาล แข็งเหมือนหนัง อาจพบเส้นเลือดอุดตัน อยู่ใต้ผิวหนัง”</b> · สไลด์หน้า 38 ลายมือ <b>“= 3<sup>rd</sup> degree burn ไม่เหลือ dermis”</b>",
 wrong={
  "A":"deep partial thickness ยังเหลือ dermis ชั้นลึก ผิวขาวซีดแต่ยังนิ่ม รับรู้แรงกดได้ และยังมี appendage งอกผิว — โจทย์ dermis หายหมด แข็งเหมือนหนังและชา · จะถูกถ้าหญิงโดนไฟลวกที่หลัง แผลขาวซีดแต่ยังนิ่ม รู้สึกแรงกดแต่ไม่รู้สึกเข็มแหลม และ biopsy ยังเหลือ dermis ส่วนลึกพร้อมรูขุมขน",
  "C":"superficial partial thickness เสียแค่ epidermis และ dermis ส่วนบน มีตุ่มน้ำใส พื้นชมพูชื้น กดซีดแล้วแดงกลับเร็ว และปวดมาก · จะถูกถ้าเด็กโดนน้ำซุปร้อนหกใส่หน้าอก เกิดตุ่มน้ำใส พื้นแผลชมพูชื้น ร้องเจ็บมากเมื่อสัมผัส และ biopsy ถึงแค่ papillary dermis",
  "D":"4° ต้องลึกผ่านผิวหนังและไขมันถึงกล้ามเนื้อ เอ็น หรือกระดูก ซึ่ง biopsy ในโจทย์ระบุว่ากล้ามเนื้อปกติ · จะถูกถ้าผู้ป่วยลมชักล้มลงในกองไฟนาน จนขณะ debridement พบกล้ามเนื้อหน้าแข้งไหม้เกรียมและเห็นกระดูก tibia",
  "E":"1° เสียเฉพาะ epidermis ผิวแดง แห้ง แสบ ไม่มีตุ่มน้ำ และหายเองภายในราว 1 สัปดาห์โดยไม่เป็นแผลเป็น · จะถูกถ้าชาวประมงตากแดดทั้งวัน มีผิวแดงแสบที่หลัง กดแล้วซีดและแดงกลับทันที ไม่มีตุ่มน้ำ"},
 trap="“ไม่ปวด” ฟังดูเหมือนแผลเบา จึงชวนเลือก 1° หรือแผลตื้น และผิวขาวซีดชวนสับสนกับ deep 2° — ตัวแยกคือความนิ่มกับ biopsy: ยังนิ่มและเหลือ dermis = deep 2° · แข็งเหมือนหนัง ชา และ dermis หายหมด = full thickness",
 summary=["Full thickness = dermis ถูกทำลายทั้งชั้น · ขาว น้ำตาล หรือดำ แข็งเหมือนหนัง ไม่ปวด",
  "ความปวดสวนทางกับความลึก: แผลตื้นปวดมาก · deep 2° รู้สึกแค่แรงกด · full thickness ชาต่อเข็ม",
  "Capillary refill: แผลตื้นกดซีดแล้วแดงกลับเร็ว · deep 2° กลับช้า · full thickness กดไม่ซีด อาจเห็นเส้นเลือดอุดตัน",
  "แผนภาพหน้า 9: 3° ลึกถึง Subcutaneous · 4° ถึง Muscle และ Bone",
  "การประเมินความลึกด้วยตาแม่นเพียงราว 60–75% แม้ผู้เชี่ยวชาญ · แผลจริงมักมีหลายความลึกปนกัน ต้องประเมินซ้ำใน 48–72 ชั่วโมง",
  "Full thickness รอบวงแขนขาหรือหน้าอก → เฝ้าระวังเลือดไปเลี้ยงส่วนปลายและการหายใจ อาจต้อง escharotomy"],
 opinion="เห็นด้วยกับคำตอบ B ความมั่นใจสูง — ลายมือสไลด์หน้า 38 “ไม่เหลือ dermis” และชีทหน้า 3 บรรยายแผลขาวหรือน้ำตาล แข็งเหมือนหนัง อาจพบเส้นเลือดอุดตัน ตรงกับลักษณะในโจทย์ทั้งหมด · จุดที่ต่างจากแนวปัจจุบัน: ชีทหน้า 3 เขียนว่าแผลระดับ 3 หายโดยการหดรั้งและการปลูกผิว ซึ่งปัจจุบันเน้น <b>early excision and grafting</b> ภายในไม่กี่วันหลังผู้ป่วยคงที่ แทนการรอให้ eschar หลุดเอง เพราะลดการติดเชื้อ ระยะนอนโรงพยาบาล และการตาย · Monstrey 2008 รายงานว่าการประเมินด้วยตาแม่นเพียงราว 60–75% แผลก้ำกึ่งจึงควรใช้ laser Doppler imaging ช่วย",
 mnemonic="<b>“ขาว แข็ง ชา = Full thickness · ยิ่งลึกยิ่งไม่เจ็บ”</b>",
 guide="Monstrey S et al. Assessment of burn depth and burn wound healing potential (Burns 2008;34:761–769); ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021); Herndon DN. Total Burn Care 5th ed. (2018)",
 variants=["ชายไฟไหม้ full thickness รอบวงต้นแขน มือเย็นซีด ชา ชีพจรเบาลง → escharotomy ทันทีข้างเตียง ไม่ต้องดมยาเพราะ eschar ชาอยู่แล้ว",
  "แผลไฟไหม้ตรงกลางขาวแข็งไม่เจ็บ แต่รอบขอบยังแดงและเจ็บมาก → แผลมีหลายความลึกปนกัน ขอบเป็น partial thickness ที่ปลายประสาทยังอยู่",
  "ช่างไฟฟ้าโดนไฟฟ้าแรงสูง ผิวเห็นเพียงจุดไหม้ดำเล็ก ๆ ที่มือ แต่แขนบวมตึงและปวดเมื่อขยับนิ้ว → กล้ามเนื้อใต้ผิวตายลึกกว่าที่เห็น ต้องผ่าตัดสำรวจและ fasciotomy"])

mk(Q, 14, [9, 38, 's3'],
 stem="A 30-year-old man has blistered scalds over 18% TBSA, and the surrounding skin over another 10% TBSA is red and painful but not blistered. How should the red, unblistered area be handled when estimating TBSA for fluid resuscitation?",
 opts=["Counted at half of its measured area",
       "Added to the partial-thickness area",
       "Excluded from the calculation",
       "Counted as full thickness if it is painful",
       "Counted only when it involves the face"],
 interp="ตุ่มน้ำ 18% ร่วมกับผิวแดงไม่มีตุ่มน้ำอีก 10% → ผิวแดงอย่างเดียวคือ 1° (superficial) · ถามว่านับส่วนนี้ใน %TBSA ที่ใช้คำนวณสารน้ำอย่างไร ต้องใช้หลักว่าสูตรให้น้ำนับเฉพาะแผล 2° ขึ้นไป",
 why="แผล<b>1° (superficial, epidermal)</b> เสียเฉพาะ epidermis ผิวแดง แห้ง แสบ ไม่มีตุ่มน้ำ กดซีดแล้วแดงกลับเร็ว หลอดเลือดใน dermis ยังปกติ จึง<b>ไม่มีการรั่วของสารน้ำออกนอกหลอดเลือดอย่างมีนัยสำคัญ</b>และไม่มีน้ำซึมออกทางแผล · สูตรให้สารน้ำทุกสูตร เช่น Parkland หรือ modified Brooke จึงใช้ %TBSA ของ<b>แผล partial thickness และ full thickness เท่านั้น</b> — 1° ไม่นับเลย ในโจทย์จึงนับ 18% ไม่ใช่ 28% · การนับผิวแดงรวมเข้าไปเป็นความผิดพลาดที่พบบ่อยของโรงพยาบาลที่ส่งต่อ ทำให้ %TBSA เกินจริงและนำไปสู่<b>การให้น้ำเกิน (fluid creep)</b> ซึ่งเพิ่มความเสี่ยงทางเดินหายใจบวม abdominal compartment syndrome และ compartment syndrome ของแขนขา · ผิวที่แดงในชั่วโมงแรกอาจเกิดตุ่มน้ำตามมาใน 24 ชั่วโมง จึงควรประเมินพื้นที่ซ้ำ · สไลด์หน้า 9 ลายมือ <b>“(<u>ไม่</u>ค่อยสนใจ 1<sup>st</sup> degree) ⟶ e.g. ตากแดดแล้วผิวแดง”</b>",
 wrong={
  "A":"การนับครึ่งค่าไม่มีในระบบใด — 1° ไม่นับเลย ส่วน partial thickness นับเต็มพื้นที่เท่ากับ full thickness · ไม่มีสถานการณ์ใดที่ผิวแดงไม่มีตุ่มน้ำถูกนับครึ่งพื้นที่ใน %TBSA เพราะการไม่นับมาจากการที่ผิวชั้นนี้ไม่รั่วสารน้ำ ไม่ใช่รั่วครึ่งเดียว",
  "B":"พื้นที่ partial thickness คือส่วนที่มีตุ่มน้ำหรือพื้นแผลชื้นซึ่งนับเต็มพื้นที่ — ผิวที่แดงอย่างเดียวยังไม่ใช่ partial thickness · จะถูกถ้าชายอีกรายมีผิวที่ไหล่แดงในวันแรก แล้ววันรุ่งขึ้นเกิดตุ่มน้ำใสพื้นชมพูชื้นทั่วบริเวณนั้น ซึ่งต้องนับพื้นที่นั้นรวมเป็น partial thickness",
  "D":"ความปวดเป็นลักษณะของแผลตื้นที่ปลายประสาทยังอยู่ ส่วน full thickness ปลายประสาทตายจึงชา — ช้อยนี้กลับด้านความสัมพันธ์ · ไม่มีสถานการณ์ใดที่ความปวดทำให้ผิวแดงไม่มีตุ่มน้ำถูกนับเป็น full thickness เพราะความลึกตัดสินจากชั้นผิวที่ถูกทำลาย และแผลที่ปวดบ่งว่าตื้น",
  "E":"หน้าเป็นตำแหน่งสำคัญเพราะเกี่ยวกับทางเดินหายใจและเป็นเกณฑ์ส่งต่อศูนย์ burn แต่ไม่เปลี่ยนกติกาการนับ %TBSA · ไม่มีสถานการณ์ใดที่ 1° ที่หน้าถูกนับเข้าสูตรให้สารน้ำขณะที่ 1° ที่อื่นไม่นับ เพราะการไม่นับมาจากความลึก ไม่ใช่ตำแหน่ง"},
 trap="ผิวแดงแสบกว้างดูน่ากลัวและอยู่ติดกับตุ่มน้ำ จึงชวนนับรวมเป็น partial thickness — ตัวแยกคือตุ่มน้ำ: แดงอย่างเดียวไม่มีตุ่มน้ำ = 1° ไม่นับ · มีตุ่มน้ำหรือพื้นแผลชื้น = 2° นับเต็มพื้นที่",
 summary=["%TBSA สำหรับสูตรให้สารน้ำ = partial thickness + full thickness เท่านั้น · 1° ไม่นับ",
  "1° = epidermis: แดง แห้ง แสบ ไม่มีตุ่มน้ำ กดซีดแดงกลับเร็ว · ตัวอย่างในลายมือ: ตากแดดแล้วผิวแดง",
  "เหตุที่ไม่นับ: หลอดเลือดใน dermis ปกติ ไม่มีการรั่วสารน้ำและไม่มีน้ำซึมทางแผล",
  "นับผิวแดงรวม → %TBSA เกินจริง → ให้น้ำเกิน (fluid creep) → ทางเดินหายใจบวม abdominal compartment syndrome",
  "เครื่องมือ: rule of nines ในผู้ใหญ่ · Lund and Browder แม่นกว่าโดยเฉพาะเด็ก · แผลกระจายใช้ฝ่ามือรวมนิ้วของผู้ป่วย ≈ 1%",
  "ผิวที่แดงอาจกลายเป็นตุ่มน้ำใน 24 ชั่วโมงแรก → ประเมินพื้นที่ซ้ำ"],
 opinion="เห็นด้วยกับคำตอบ C ความมั่นใจสูง — ลายมือสไลด์หน้า 9 บอกว่าไม่ค่อยสนใจ 1° และลายมือหน้า 38 ระบุว่า 1° เสียแค่ epidermis ตรงกับ ABLS 2018 ที่ให้ไม่นับ superficial burn ใน %TBSA · จุดที่ควรระวัง: ตารางในชีทหน้า 3 จัดระดับที่ 1 อยู่ใต้หัว Partial Thickness Burns ซึ่งอาจทำให้เข้าใจผิดว่านับรวมกับ partial thickness ได้ — ศัพท์ปัจจุบันของ ABA และ ISBI แยก 1° เป็น superficial burn ต่างหาก และนับเฉพาะ superficial partial thickness ขึ้นไป",
 mnemonic="<b>“แดงเฉย ๆ ไม่นับ · พองแล้วค่อยนับ”</b>",
 guide="American Burn Association. Advanced Burn Life Support Provider Manual (2018 update); ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021); Saffle JR. The phenomenon of fluid creep in acute burn resuscitation (J Burn Care Res 2007;28:382–395)",
 variants=["เด็ก 4 ขวบน้ำร้อนลวกทั้งหน้าอกและแขนขวา ส่วนใหญ่เป็นตุ่มน้ำ → ประเมินพื้นที่ด้วย Lund and Browder ไม่ใช้ rule of nines ผู้ใหญ่ เพราะสัดส่วนศีรษะเด็กใหญ่กว่าขา",
  "ผู้ป่วยไฟไหม้เป็นหย่อมกระจายทั่วขาทั้งสองข้าง → ประมาณพื้นที่ด้วยฝ่ามือรวมนิ้วของผู้ป่วยเอง ซึ่งเท่ากับราว 1% TBSA ต่อฝ่ามือ",
  "ผู้ป่วยถูกส่งต่อมาพร้อม %TBSA 45% แต่ตรวจซ้ำพบตุ่มน้ำและแผลลึกจริงเพียง 25% ที่เหลือแค่ผิวแดง → คำนวณสารน้ำใหม่ด้วย 25% แล้วปรับตาม urine output"])

mk(Q, 15, [39],
 stem="A 30-year-old woman's deep partial-thickness forearm burn heals from many epithelial islands across its base. Where do these islands originate?",
 opts=["Keratinocytes lining surviving hair follicles and glands",
       "Endothelial cells of new dermal capillaries",
       "Fibroblasts migrating up from the subcutaneous fat",
       "Satellite cells of the underlying skeletal muscle",
       "Melanocytes migrating inward from the surrounding wound edge"],
 interp="แผล 2° ลึกที่แขนงอกผิวเป็นเกาะเล็ก ๆ กระจายทั่วก้นแผล ไม่ใช่คืบจากขอบอย่างเดียว → ถามว่าเกาะผิวมาจากไหน ต้องใช้หลักว่า keratinocyte สำรองซ่อนอยู่ใน skin appendage ที่ฝังใน dermis ที่เหลือ",
 why="เซลล์สร้างผิวคือ <b>basal (germinative) layer</b> ของ epidermis ซึ่งแผลระดับ 2 ทำลายเกือบหมด แต่ basal keratinocyte ยัง<b>บุลงไปตามผนังรูขุมขน ต่อมไขมัน และท่อต่อมเหงื่อ</b>ที่ฝังลึกใน dermis · เมื่อ dermis ยังเหลือ appendage แต่ละอันจึงเป็น<b>แหล่ง keratinocyte สำรอง</b> เซลล์แบ่งตัวและคืบออกจากปากรูขุมขนหรือท่อต่อมขึ้นมาคลุมผิวเป็น<b>เกาะเล็ก ๆ กระจายทั่วก้นแผล</b> แล้วเกาะขยายมาชนกันพร้อมกับผิวที่คืบจากขอบ แผล partial thickness จึงหายได้เองโดยไม่ต้องปลูกผิว · งานวิจัยปัจจุบันพบ stem cell บริเวณ <b>bulge</b> ของรูขุมขน และพบว่าต่อมเหงื่อ eccrine ก็เป็นแหล่งงอกผิวสำคัญในคน · ยิ่งแผลลึก appendage ที่เหลือยิ่งน้อยและห่างกัน เกาะงอกผิวจึงน้อย แผล 2° ลึกจึงหายช้ากว่าแผลตื้นหลายสัปดาห์ · สไลด์หน้า 39 ลายมือ <b>“<u>แต่</u> keratinocyte ยังมีซ่อนใน skin appendages e.g. hair follicle, sebaceous gl, sweat gl”</b> และ <b>“└ ฝังใน dermis ∴ ถ้า dermis เหลือ ⟶ งอก skin ใหม่ได้”</b>",
 wrong={
  "B":"Endothelial cell ของ capillary ที่งอกใหม่ (angiogenesis) สร้างหลอดเลือดให้เนื้อ granulation และเลี้ยงผิวที่กำลังงอก แต่ไม่เปลี่ยนเป็น keratinocyte · ไม่มีสถานการณ์ใดที่เกาะผิวกลางแผลไหม้มาจาก endothelial cell เพราะเซลล์นี้เป็นคนละสายเซลล์กับ epithelium และทำหน้าที่สร้างหลอดเลือดเท่านั้น",
  "C":"Fibroblast จากไขมันใต้ผิวและ dermis ที่เหลือสร้าง collagen เนื้อ granulation และกลายเป็น myofibroblast ที่ทำให้แผลหดรั้ง — เป็นส่วนของ dermis ไม่ใช่ผิวชั้นนอก · ไม่มีสถานการณ์ใดที่เกาะผิวมาจาก fibroblast เพราะ fibroblast เป็นเซลล์ mesenchyme ที่ไม่สร้าง keratin หรือ epidermis",
  "D":"Satellite cell เป็นเซลล์ต้นกำเนิดใต้ basal lamina ของใยกล้ามเนื้อลาย ใช้ซ่อมกล้ามเนื้อที่บาดเจ็บ ซึ่งแผล 2° ไม่ได้ลึกถึง · ไม่มีสถานการณ์ใดที่เกาะผิวของแผลไหม้มาจาก satellite cell เพราะเซลล์นี้เปลี่ยนเป็นได้เฉพาะเซลล์กล้ามเนื้อ",
  "E":"Melanocyte อยู่ปนใน basal layer สร้างเม็ดสีส่งให้ keratinocyte และกลับมาช้าหลังแผลหาย แผลไหม้จึงมักด่างหรือคล้ำ — ไม่สร้างเซลล์ผิว · ไม่มีสถานการณ์ใดที่ melanocyte สร้างเกาะผิวใหม่ และเซลล์ที่คืบจากขอบแผลจริงคือ keratinocyte ซึ่งให้ภาพการคืบจากขอบ ไม่ใช่เกาะกลางแผล"},
 trap="ช้อย E ใส่คำว่า migrating from the wound edge ซึ่งเป็นกลไกจริงของการหายจากขอบ จึงชวนให้เลือก — ตัวแยกคือคำว่า “เกาะกลางแผล”: ต้องมีแหล่งอยู่ในก้นแผลเอง คือ appendage ใน dermis ที่เหลือ และเซลล์ที่งอกคือ keratinocyte ไม่ใช่ melanocyte",
 summary=["เกาะผิวกลางแผล = keratinocyte จาก appendage ที่เหลือใน dermis: รูขุมขน ต่อมไขมัน ต่อมเหงื่อ",
  "ลายมือหน้า 39: basal layer เป็นตัวสร้างผิว burn มักทำลายเกือบหมด แต่ร่างกายมี reservoir ของ keratinocyte ที่ hair follicle",
  "Partial thickness หายสองทาง: เกาะจาก appendage ในก้นแผล + คืบจากขอบ · full thickness เหลือแค่ขอบ",
  "Donor site ของ split-thickness graft หายเองด้วยกลไกเดียวกันในราว 7–14 วัน และตัดซ้ำได้",
  "ยิ่งลึก appendage ยิ่งน้อยและห่าง → หายช้า แผลเป็นมาก · แผลที่คาดว่าเกิน 3 สัปดาห์ควรปลูกผิว",
  "เซลล์อื่นในแผล: fibroblast สร้าง collagen และหดรั้ง · endothelial cell สร้างหลอดเลือด · melanocyte ให้สี"],
 opinion="เห็นด้วยกับคำตอบ A ความมั่นใจสูง — ลายมือสไลด์หน้า 39 อธิบายตรงตัวว่า keratinocyte ซ่อนใน hair follicle, sebaceous gland และ sweat gland ที่ฝังใน dermis · ความรู้ปัจจุบันเพิ่มรายละเอียดว่า stem cell ที่ bulge ของรูขุมขนเข้ามาช่วยปิดแผลระยะแรก (Ito 2005) และในผิวคนต่อมเหงื่อ eccrine เป็นแหล่งงอกผิวที่สำคัญไม่น้อยกว่ารูขุมขน (Rittié 2013) · หลักการทางคลินิกไม่เปลี่ยน: เหลือ dermis และ appendage = หายเองได้",
 mnemonic="<b>“เกาะกลางแผล = ขน ไขมัน เหงื่อ”</b>",
 guide="Rittié L et al. Eccrine sweat glands are major contributors to reepithelialization of human wounds (Am J Pathol 2013;182:163–171); Ito M et al. Stem cells in the hair follicle bulge contribute to wound repair (Nat Med 2005;11:1351–1354); Herndon DN. Total Burn Care 5th ed. (2018)",
 variants=["แผล 2° ลึกที่ติดเชื้อจนเนื้อตายลึกลง (wound conversion) → appendage ที่เหลือถูกทำลาย แผลกลายเป็น full thickness ต้องตัดเนื้อตายและปลูกผิว",
  "แผล 2° ตื้นหายใน 2 สัปดาห์ แต่ผิวใหม่ด่างขาวสลับคล้ำเป็นหย่อม → melanocyte กลับมาช้าและไม่สม่ำเสมอ ต้องป้องกันแดดจนแผลเป็น mature",
  "แผล partial thickness ที่ปิดด้วย dressing ชุ่มชื้น → keratinocyte คืบได้เร็วกว่าแผลที่ปล่อยให้แห้งเป็นสะเก็ด เพราะเซลล์คืบบนพื้นชื้นได้ง่าย"])

mk(Q, 16, [39, 49],
 stem="A 52-year-old man has a 3-cm forearm burn with all dermal appendages destroyed. Why can its base not re-epithelialize?",
 opts=["Granulation tissue cannot form on subcutaneous fat",
       "Fibroblasts are absent from the wound bed",
       "Burn toxins block collagen synthesis in the base",
       "No keratinocyte reservoir remains in the base",
       "All blood vessels at the wound edge are thrombosed"],
 interp="แผลไหม้ 3 cm ที่ appendage ใน dermis ถูกทำลายหมด = full thickness → ถามว่าทำไมก้นแผลงอกผิวเองไม่ได้ ต้องใช้หลักว่าเซลล์สร้างผิวสำรองอยู่ใน appendage ที่ฝังใน dermis เมื่อ dermis หายหมดจึงไม่เหลือแหล่ง keratinocyte",
 why="การงอกผิวต้องมี<b>keratinocyte ที่มีชีวิต</b> ซึ่งในแผลไหม้มาจากสองแหล่ง: basal layer ที่บุ appendage ใน dermis (ให้เกาะงอกผิวจากก้นแผล) และผิวปกติที่ขอบแผล · แผล<b>full thickness</b> dermis และ appendage ถูกทำลายหมด จึง<b>ไม่เหลือแหล่ง keratinocyte ในก้นแผล</b> — ก้นแผลยังสร้าง <b>granulation tissue</b> ได้ตามปกติจาก fibroblast และหลอดเลือดใหม่ของเนื้อเยื่อด้านล่าง แต่ไม่มีผิวงอกขึ้นมาคลุม · แผลจึงหายได้ทางเดียวคือ<b>ผิวคืบจากขอบ</b>ซึ่งช้าและได้ระยะจำกัด ร่วมกับ<b>การหดรั้ง (contraction)</b> โดย myofibroblast ซึ่งเหมาะกับแผลเล็กอย่าง 3 cm ที่ไม่ข้ามข้อ · แผลใหญ่หรือข้ามข้อต้องตัดเนื้อตายและปลูกผิว มิฉะนั้นจะหายช้ามาก เกิด contracture และได้แผลเป็นบางที่แตกซ้ำง่าย · สไลด์หน้า 49 ลายมือ <b>“⟶ dermis หายหมด = <u>no</u> skin appendages ⟶ heal จากก้นแผลไม่ได้”</b> และ <b>“· แผลเล็ก ⟶ ปล่อย 2° healing : แผลหดจากข้าง ๆ มาปิด”</b>",
 wrong={
  "A":"ก้นแผล full thickness สร้าง granulation ได้ทั้งบนไขมัน fascia หรือกล้ามเนื้อ แม้บนไขมันจะขึ้นช้ากว่าเพราะเลือดน้อย — granulation เป็นพื้นให้ผิวคืบมา ไม่ใช่ตัวสร้างผิว · ไม่มีสถานการณ์ใดที่การไม่มี granulation เป็นเหตุหลักที่ก้นแผลงอกผิวไม่ได้ เพราะแม้ granulation ขึ้นเต็มแผลก็ยังไม่มี keratinocyte ให้งอก",
  "B":"Fibroblast เคลื่อนมาจากเนื้อเยื่อรอบแผลและด้านล่างได้เสมอ สร้าง collagen และกลายเป็น myofibroblast ที่ทำให้แผล full thickness หดรั้ง — การหดรั้งที่เห็นคือหลักฐานว่ามี fibroblast · ไม่มีสถานการณ์ใดที่การขาด fibroblast อธิบายว่าทำไมก้นแผลไม่งอกผิว เพราะ fibroblast ไม่ได้สร้าง epidermis ตั้งแต่ต้น",
  "C":"ไม่มีสารพิษจากแผลไหม้ที่หยุดการสร้าง collagen — แผลไหม้กลับสร้าง collagen มากเกินจนเกิด hypertrophic scar และ contracture · ไม่มีสถานการณ์ใดที่ burn toxin เป็นเหตุให้ก้นแผลงอกผิวไม่ได้ เพราะปัญหาของแผล full thickness คือขาดเซลล์สร้างผิว ไม่ใช่ขาด collagen",
  "E":"ขอบแผลไหม้อยู่ใน zone of hyperemia ที่เลือดมาเลี้ยงมาก และเป็นจุดที่ผิวคืบเข้ามาได้ — เส้นเลือดอุดตันเป็นภาพของ eschar ตรงกลางแผล · ไม่มีสถานการณ์ใดที่เส้นเลือดที่ขอบแผลเป็นเหตุให้ก้นแผลงอกผิวไม่ได้ เพราะแหล่งงอกผิวของก้นแผลคือ appendage ในก้นแผลเอง ไม่ได้มาจากขอบ"},
 trap="ช้อย E ฟังดูถูกเพราะ eschar ไม่มีเลือดและเห็นเส้นเลือดอุดตันได้ — แต่คำถามถามเรื่อง “ก้นแผล” ซึ่งต้องตอบด้วยแหล่งเซลล์สร้างผิว: ไม่มี appendage = ไม่มี keratinocyte สำรอง ส่วนเลือดและ granulation มีได้ตามปกติ",
 summary=["Full thickness: dermis หายหมด = ไม่มี appendage = ไม่มี keratinocyte สำรองในก้นแผล",
  "สไลด์หน้า 49 Natural history: no epithelial elements · scar tissue · granulation · contracture",
  "ทางหายที่เหลือ: ผิวคืบจากขอบ + การหดรั้งโดย myofibroblast",
  "ลายมือหน้า 49: แผลเล็ก → ปล่อย secondary healing แผลหดจากข้าง ๆ มาปิด · แผลใหญ่ → skin graft",
  "ปล่อยแผลใหญ่หายเอง → หายช้าหลายเดือน contracture ข้ามข้อ แผลเป็นบางไม่คงทน แตกซ้ำ และระยะยาวเสี่ยง Marjolin ulcer",
  "ก้นแผลสร้าง granulation ได้ปกติ — granulation เป็นพื้นให้ผิวคืบมาหรือรองรับ graft ไม่ใช่ตัวสร้างผิว"],
 opinion="เห็นด้วยกับคำตอบ D ความมั่นใจสูง — ลายมือสไลด์หน้า 39 และ 49 อธิบายต่อกันว่า keratinocyte ซ่อนใน appendage และเมื่อ dermis หายหมดก้นแผลจึงงอกผิวไม่ได้ · ตรงกับแนวปัจจุบันที่ปล่อยแผล full thickness ขนาดเล็กในตำแหน่งที่ไม่ข้ามข้อให้หายเองได้ ส่วนแผลที่ใหญ่กว่านั้นทำ early excision and grafting · เมื่อผิวตัวเองไม่พอ ปัจจุบันใช้ dermal substitute เช่น Integra ทดแทน dermis ก่อนปลูกผิวบาง ซึ่งสไลด์ไม่ได้กล่าวถึง",
 mnemonic="<b>“ไม่มี dermis = ไม่มีเมล็ดพันธุ์ผิว · ปิดได้แค่จากขอบกับหดรั้ง”</b>",
 guide="Herndon DN. Total Burn Care 5th ed. (2018) — Wound healing and burn wound management; Sabiston Textbook of Surgery 21st ed. (2022) — Burns; ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021)",
 variants=["ผู้ป่วย full thickness 50% ผิวดีเหลือไม่พอทำ autograft ทั้งหมด → ตัดเนื้อตายแล้วปิดด้วย Integra รอ neodermis 2–3 สัปดาห์ แล้วปลูกผิวบางทับ",
  "แผล full thickness ที่ปลูก STSG แล้ว ผิวใหม่แห้งและคันตลอด → ต่อมเหงื่อและต่อมไขมันไม่ได้ติดมากับ graft บาง ต้องทาครีมให้ชุ่มชื้นสม่ำเสมอ",
  "ใช้ cultured epidermal autograft ปิดแผล full thickness กว้างโดยตรงบน granulation → ติดยากและเปราะแตกง่าย เพราะไม่มี dermis รองรับ"])

mk(Q, 17, [39],
 stem="A 27-year-old woman's scalp scald healed faster than a burn of similar depth on her palm. What best explains this?",
 opts=["Hair shafts conducted heat away, so the scalp burn was shallower",
       "Palmar dermis lacks a dependable blood supply",
       "Palmar skin has no dermal layer",
       "Scalp epidermis lacks a basal layer",
       "Dense hair follicles supply keratinocytes for regrowth"],
 interp="แผลความลึกใกล้กันที่หนังศีรษะหายเร็วกว่าที่ฝ่ามือ → ถามเหตุผล ตัวแปรที่ต่างคือจำนวนและความลึกของ appendage ต่อพื้นที่ ต้องใช้หลักว่า keratinocyte สำรองอยู่ในรูขุมขนที่ฝังใน dermis",
 why="อัตราการหายของแผล partial thickness ขึ้นกับ<b>จำนวน appendage ที่เหลือต่อพื้นที่</b> เพราะแต่ละรูขุมขนหรือต่อมเป็นจุดตั้งต้นของเกาะงอกผิว · <b>หนังศีรษะ</b>มีรูขุมขนหนาแน่นมาก ราว 100,000 เส้นทั่วศีรษะ และโคนรูขุมขน (bulb) ฝัง<b>ลึกลงถึงไขมันใต้ผิว</b> แผลแม้ลึกเกือบหมด dermis จึงยังเหลือแหล่ง keratinocyte จำนวนมากชิดกัน เกาะงอกผิวมาชนกันเร็ว · <b>ฝ่ามือ</b>เป็นผิว glabrous ไม่มีรูขุมขนและต่อมไขมัน มีเพียงต่อมเหงื่อ eccrine ซึ่งท่อเล็กและเป็นแหล่งงอกผิวที่น้อยกว่า แผลความลึกเท่ากันจึงหายช้ากว่า · หลักเดียวกันทำให้หนังศีรษะเป็น <b>donor site ที่ดี</b>: หายเร็วราว 1 สัปดาห์ ตัดซ้ำได้หลายครั้ง และผมขึ้นปิดรอยแผล จึงนิยมในเด็กและผู้ป่วยแผลกว้าง · สไลด์หน้า 39 ลายมือ <b>“basal layer เป็นตัวสร้างผิวหนัง ∴ ร่างกายมีการ reservoir ของ keratinocyte at hair follicle”</b>",
 wrong={
  "A":"เส้นผมเป็น keratin ที่นำความร้อนไม่ดีและติดไฟได้ ไม่ได้ช่วยระบายความร้อนออก และโจทย์ระบุว่าความลึกใกล้เคียงกันอยู่แล้ว · ไม่มีสถานการณ์ใดที่เส้นผมนำความร้อนออกจากหนังศีรษะจนแผลตื้นลง เพราะ keratin มีคุณสมบัติเป็นฉนวน และผมที่ติดไฟยังเป็นเชื้อเพลิงเพิ่มความร้อนให้หนังศีรษะด้วย",
  "B":"ฝ่ามือมีหลอดเลือดเลี้ยงดีมากจาก superficial และ deep palmar arch ผ่าน common digital artery และแผลในบริเวณนี้มีเลือดเลี้ยงเพียงพอ · ไม่มีสถานการณ์ใดที่ dermis ของฝ่ามือปกติขาดเลือดเลี้ยงจนเป็นเหตุให้แผลหายช้ากว่าหนังศีรษะ เพราะความต่างของการหายมาจากจำนวน appendage ไม่ใช่เลือด",
  "C":"ฝ่ามือมีทั้ง epidermis ที่หนาที่สุดชนิดหนึ่งของร่างกาย (มี stratum lucidum) และ dermis หนาที่ยึดกับ palmar aponeurosis · ไม่มีสถานการณ์ใดที่ผิวฝ่ามือไม่มี dermis เพราะผิวหนังทุกตำแหน่งประกอบด้วย epidermis และ dermis เสมอ ต่างกันแค่ความหนาและชนิดของ appendage",
  "D":"ผิวทุกตำแหน่งมี basal layer เป็นแถวเซลล์ล่างสุดของ epidermis และหนังศีรษะยังมี basal keratinocyte บุลงไปตามรูขุมขนลึกจำนวนมาก ซึ่งกลับเป็นเหตุที่หายเร็ว · ไม่มีสถานการณ์ใดที่ epidermis ของหนังศีรษะไม่มี basal layer เพราะ epidermis ทุกแห่งต้องอาศัยชั้นนี้สร้างเซลล์ใหม่"},
 trap="ช้อย A อ้างว่าแผลตื้นกว่าจริง ซึ่งเลี่ยงเงื่อนไข “ความลึกใกล้เคียงกัน” ในโจทย์ ส่วนช้อยที่ว่าฝ่ามือขาด dermis หรือเลือดผิดกายวิภาค — เมื่อความลึกเท่ากัน ตัวแปรที่เหลือคือจำนวนและความลึกของ appendage ต่อพื้นที่",
 summary=["ความลึกเท่ากัน → หายเร็วหรือช้าตามจำนวนและความลึกของ appendage ต่อพื้นที่",
  "หนังศีรษะ: รูขุมขนหนาแน่น โคนฝังลึกถึงไขมัน → หายเร็ว · เป็น donor site ที่หายราว 1 สัปดาห์ ตัดซ้ำได้ ผมปิดรอย",
  "ฝ่ามือ ฝ่าเท้า: ผิว glabrous ไม่มีรูขุมขนและต่อมไขมัน มีแต่ต่อมเหงื่อ eccrine → แหล่งงอกผิวน้อยกว่า",
  "หน้า: appendage มากและเลือดเลี้ยงดี แผลตื้นหายเร็ว",
  "ผู้สูงอายุและเด็กเล็ก: dermis บาง appendage อยู่ตื้น → แผลที่ดูตื้นมักลึกจริงและหายช้า",
  "ลายมือหน้า 39: ร่างกายมี reservoir ของ keratinocyte ที่ hair follicle"],
 opinion="เห็นด้วยกับคำตอบ E ความมั่นใจสูง — ลายมือสไลด์หน้า 39 ระบุว่า reservoir ของ keratinocyte อยู่ที่ hair follicle ซึ่งหนังศีรษะมีหนาแน่นและฝังลึก · ข้อควรรู้เพิ่ม: Rittié 2013 พบว่าต่อมเหงื่อ eccrine ซึ่งฝ่ามือมีหนาแน่นมากก็เป็นแหล่งงอกผิวที่สำคัญในคน ฝ่ามือจึงไม่ได้ไร้แหล่งงอกผิว เพียงแต่รูขุมขนบนหนังศีรษะใหญ่กว่า แน่นกว่า และฝังลึกถึงไขมันมากกว่า · ในทางคลินิก แผลลึกที่ฝ่ามือมักพิจารณาปลูกผิวหนาหรือ full-thickness graft เพื่อคงหน้าที่การกำมือ",
 mnemonic="<b>“ขนแน่น หายไว · ฝ่ามือไร้ขน หายช้า”</b>",
 guide="Rittié L et al. Eccrine sweat glands are major contributors to reepithelialization of human wounds (Am J Pathol 2013;182:163–171); Grabb and Smith's Plastic Surgery 8th ed. (2020) — Skin grafts; Herndon DN. Total Burn Care 5th ed. (2018)",
 variants=["แผล deep partial thickness ที่หลังซึ่ง dermis หนาแต่รูขุมขนห่าง → หายช้ากว่าแผลลึกเท่ากันที่หน้า",
  "เด็กมีแผลลึกที่ฝ่ามือไม่หายใน 3 สัปดาห์ → พิจารณา full-thickness skin graft เพื่อคงความยืดหยุ่นในการกำและแบมือ",
  "ผู้ป่วยเคยได้รับรังสีรักษาที่หนังศีรษะจนผมร่วงถาวร แล้วไฟไหม้บริเวณเดิม → รูขุมขนถูกทำลายจากรังสี แผลหายช้าแม้เป็นตำแหน่งที่ปกติหายเร็ว"])

mk(Q, 18, [11, 's5'],
 stem="A 35-year-old man has 45% TBSA flame burns of the trunk and legs. Within hours his unburned arms and face become markedly edematous despite appropriate resuscitation volumes. What is the main mechanism?",
 opts=["Circulating mediators increasing capillary leak",
       "Lymphatic obstruction from circumferential eschar",
       "Hypoalbuminemia from urinary protein loss",
       "Direct heat injury to capillaries of unburned skin",
       "Sodium overload from Ringer's lactate infusion"],
 interp="แผลไหม้ 45% ที่ลำตัวและขา แต่แขนและหน้าที่ไม่ไหม้บวมมากภายในไม่กี่ชั่วโมงทั้งที่ให้น้ำเหมาะสม → ถามกลไกหลักของการบวมในส่วนที่ไม่ไหม้ ต้องใช้หลักการรั่วทั่วร่างจากสารสื่อการอักเสบเมื่อแผลเกิน 25%",
 why="ที่<b>บริเวณแผล</b> capillary รั่วเพราะความร้อนทำลายผนังหลอดเลือดโดยตรงร่วมกับสารสื่อเฉพาะที่ แต่เมื่อแผล<b>เกินราว 25% TBSA</b> สารสื่อการอักเสบจำนวนมากถูกปล่อยเข้า<b>กระแสเลือด</b> ได้แก่ histamine, serotonin, bradykinin, prostaglandins, leukotrienes, complement, oxygen free radicals และ cytokine เช่น IL-6 และ TNF-α ทำให้ endothelium ทั่วร่างหดตัวเกิดช่องว่างระหว่างเซลล์ <b>capillary permeability จึงเพิ่มทั้งในส่วนที่ไหม้และไม่ไหม้</b> โปรตีนและน้ำรั่วออกสู่ interstitium — ภาพคล้าย systemic inflammatory response แบบ sepsis · ผลคือ<b>บวมทั่วร่าง</b>รวมหน้า หนังตา แขน และผนังท้องที่ไม่ไหม้ และเสี่ยงทางเดินหายใจบวมหรือ abdominal compartment syndrome · การรั่วเริ่มทันทีหลังไหม้ บวมสูงสุดใน 8–24 ชั่วโมง แล้วค่อยลดลงเมื่อ endothelium ฟื้น · ชีทหน้า 5 <b>“สาเหตุของการเพิ่ม Capillary Permeability … สารเหล่านี้ได้แก่ Vasoactive Amines, Complement, Prostaglandins และ Lenkotrienes”</b> · สไลด์หน้า 11 ลายมือ <b>“└ เกิดจาก cytokines ⟶ เกิดรูรั่ว ~ septic shock”</b>",
 wrong={
  "B":"eschar รอบวงที่แข็งไม่ยืดจะรัดทางกลับของหลอดเลือดดำและน้ำเหลือง ทำให้ส่วนปลายต่อ eschar บวม ตึง และขาดเลือดได้ แต่ไม่อธิบายแขนและหน้าที่อยู่ห่างจากแผลที่ลำตัวและขา · จะถูกถ้าชายอีกรายมีแผล full thickness รอบวงที่ปลายแขนเท่านั้น แล้วมือข้างนั้นที่ไม่ไหม้บวมตึงและเย็นลงเรื่อย ๆ จนต้องทำ escharotomy",
  "C":"การเสียโปรตีนทางปัสสาวะทำให้ oncotic pressure ต่ำเป็นกลไกของ nephrotic syndrome · ใน burn ระยะหลังโปรตีนต่ำจากการรั่วก็เสริมการบวมได้ แต่ไม่ใช่ทางปัสสาวะและไม่ใช่กลไกหลักในไม่กี่ชั่วโมงแรก · จะถูกถ้าเด็กชาย 5 ขวบหนังตาบวมตอนเช้าแล้วลามบวมทั้งตัว ปัสสาวะเป็นฟอง albumin ในเลือดต่ำและโปรตีนในปัสสาวะสูงมาก",
  "D":"ความร้อนทำลายหลอดเลือดโดยตรงได้เฉพาะบริเวณที่สัมผัสความร้อนคือตัวแผลเอง ส่วนที่ไม่ไหม้ตามนิยามไม่ได้รับความร้อนพอจะทำลาย capillary · ไม่มีสถานการณ์ใดที่ความร้อนโดยตรงอธิบายการบวมของผิวที่ไม่ไหม้ได้ เพราะขัดกันเองในตัว ถ้าความร้อนทำลาย capillary ได้ ผิวส่วนนั้นก็คือส่วนที่ไหม้",
  "E":"Ringer's lactate มี Na ราว 130 mmol/L ต่ำกว่าพลาสมาเล็กน้อย การให้มากเกินความต้องการ (fluid creep) ทำให้บวมเพิ่มได้ แต่โจทย์ระบุว่าให้ปริมาณเหมาะสม · จะถูกถ้าชายอีกรายมีแผลไหม้เพียง 10% แต่ถูกคำนวณ %TBSA ผิดจนได้ Ringer's lactate หลายลิตรเกินจำเป็น แล้วบวมทั่วตัวจากน้ำและเกลือเกิน"},
 trap="ช้อย D มีคำว่า capillary เหมือนคำตอบ และช้อย E ชวนคิดว่าบวมจากการให้น้ำ — ตัวแยกคือ “ส่วนที่ไม่ไหม้บวมภายในไม่กี่ชั่วโมง” ในแผลเกิน 25% ทั้งที่ให้น้ำเหมาะสม: ต้องเป็นสารสื่อที่ไหลไปทั่วร่าง ไม่ใช่ความร้อนหรือปริมาณน้ำ",
 summary=["แผลเกิน 25%: สารสื่อเข้ากระแสเลือด → capillary รั่วทั่วร่าง ทั้งส่วนที่ไหม้และไม่ไหม้",
  "บริเวณแผล: ความร้อนทำลายหลอดเลือดโดยตรง + สารสื่อเฉพาะที่ · ส่วนที่ไม่ไหม้: สารสื่อทั่วร่างอย่างเดียว",
  "สารสื่อในชีทหน้า 5: vasoactive amines, complement, prostaglandins, leukotrienes · เพิ่มเติม: bradykinin, oxygen free radicals, IL-6, TNF-α",
  "ลายมือหน้า 11: ส่วน unburned รั่วเพราะ cytokines เปรียบกับ septic shock",
  "ผลทางคลินิก: หน้า หนังตา ทางเดินหายใจ และผนังท้องบวมแม้ไม่ไหม้ → เฝ้าระวังทางเดินหายใจและความดันในกระเพาะปัสสาวะ",
  "เมื่อ endothelium ฟื้นหลังราว 24 ชั่วโมง การรั่วลดลง และน้ำกลับเข้าหลอดเลือดในวันที่ 2–5 พร้อมปัสสาวะออกมากขึ้น"],
 opinion="เห็นด้วยกับคำตอบ A ความมั่นใจสูง — สไลด์หน้า 11 ให้ capillary permeability เพิ่มทั้ง burned และ unburned tissue เมื่อเกิน 25% และลายมือระบุว่าส่วน unburned เกิดจาก cytokines ส่วนชีทหน้า 5 ระบุชนิดสารสื่อ · ตัวเลข 25% มาจากการทดลองในสัตว์ของ Arturson ปี 1979 ในคนเกณฑ์ไม่คมชัดขนาดนั้น ตำราปัจจุบันกล่าวราว 20–30% · ความรู้ปัจจุบันเพิ่มบทบาทของ glycocalyx บนผิว endothelium ที่ถูกทำลายหลังไหม้",
 mnemonic="<b>“เกิน 25 รั่วทั้งตัว · ไม่ไหม้ก็บวมเพราะ cytokine”</b>",
 guide="Arturson G (Acta Physiol Scand Suppl 1979;463:111–122); Herndon DN. Total Burn Care 5th ed. (2018) — Pathophysiology of burn shock and burn edema; Jeschke MG et al. Burn injury (Nat Rev Dis Primers 2020;6:11)",
 variants=["ผู้ป่วยไฟไหม้ 60% ที่ลำตัว ได้น้ำตามสูตร 18 ชั่วโมงต่อมาเสียงแหบและมี stridor แม้หน้าและคอไม่ไหม้ → ทางเดินหายใจบวมจากการรั่วทั่วร่าง ใส่ท่อช่วยหายใจก่อนบวมปิด",
  "ผู้ป่วยไฟไหม้ 55% ได้สารน้ำปริมาณมาก ท้องตึง ปัสสาวะลด ความดันช่วยหายใจสูงขึ้น → วัดความดันในกระเพาะปัสสาวะ สงสัย abdominal compartment syndrome",
  "ผู้ป่วยไฟไหม้ 70% ได้สารน้ำมหาศาล หนังตาบวมตึงจนลืมตาไม่ได้ ความดันในลูกตาสูง → orbital compartment syndrome ทำ lateral canthotomy"])

mk(Q, 19, [11, 's5'],
 stem="In thermal injury, above what TBSA does capillary permeability increase in unburned as well as burned tissue?",
 opts=["More than 10%",
       "More than 5%",
       "Only above 80%",
       "More than 50%",
       "More than 25%"],
 interp="ถามตัวเลขเกณฑ์ขนาดแผล (%TBSA) ที่การรั่วของ capillary ขยายจากเฉพาะแผลไปถึงเนื้อเยื่อที่ไม่ไหม้ทั่วร่าง ตามงานคลาสสิกของ Arturson ซึ่งเป็นพื้นฐานว่าทำไมแผลใหญ่จึงบวมทั้งตัวและช็อก",
 why="Arturson (1979) ลวกสัตว์ทดลองด้วยความร้อนในขนาดต่าง ๆ แล้ววัดการรั่วของสารโมเลกุลใหญ่ออกจากหลอดเลือด พบว่าเมื่อแผล<b>เกิน 25% TBSA</b> capillary permeability เพิ่ม<b>ทั้งในผิวที่ไหม้และผิวปกติทั่วร่างกาย</b> ขณะที่แผลเล็กกว่านี้รั่วเฉพาะบริเวณแผล · เหตุคือแผลใหญ่ปล่อยสารสื่อการอักเสบมากพอจะเข้ากระแสเลือดและกระทบ endothelium ทั้งระบบ ผลคือน้ำและโปรตีนออกสู่ interstitium อย่างมาก เกิด <b>hypovolemia และบวมทั่วร่าง</b> · ตัวเลขนี้อธิบายว่าทำไมแผลใหญ่ต้องให้สารน้ำทางหลอดเลือดปริมาณมาก แต่<b>ไม่ใช่เกณฑ์เริ่มให้น้ำ</b>โดยตรง — แนวปัจจุบันเริ่ม IV resuscitation ในผู้ใหญ่ราว 15–20% และเด็กราว 10% เพราะแผลขนาดนั้นก็เสียน้ำเฉพาะที่มากพอจะต้องชดเชย · ชีทหน้า 5 <b>“ในสัตว์ทดลองที่ได้รับบาดเจ็บจากบาดแผลไฟไหม้น้ำร้อนลวกเกิน 25 % ของพื้นที่ผิวของร่างกาย จะมีการเพิ่มขึ้นของ Capillary Permeability ทั้งในผิวหนังส่วนที่ได้รับบาดเจ็บและผิวหนังปกติทั่วร่างกาย”</b> · สไลด์หน้า 11 ลายมือ <b>“เอาหนูลวกน้ำร้อน ⟶ ถ้า burn ≥ 25% ของพ.ท.ผิว = หนูจะซึมแล้วตาย (&lt; 25% จะซึมแล้วค่อย ๆ หาย)”</b>",
 wrong={
  "A":"10% เป็นตัวเลขของเกณฑ์อื่นใน burn เช่น เกณฑ์เริ่มให้สารน้ำทางหลอดเลือดในเด็ก และเกณฑ์รับไว้หรือส่งต่อ — ไม่ใช่จุดที่การรั่วขยายไปทั่วร่าง · ไม่มีสถานการณ์ใดที่ 10% เป็นเกณฑ์คลาสสิกของการรั่วในเนื้อเยื่อที่ไม่ไหม้ เพราะตัวเลขนี้มาจากการทดลองของ Arturson ซึ่งให้ 25%",
  "B":"แผล 5% บวมเฉพาะบริเวณแผล ส่วนอื่นของร่างกายปกติ และผู้ใหญ่ส่วนใหญ่ดื่มน้ำทดแทนได้โดยไม่ต้องให้สารน้ำตามสูตร · ไม่มีสถานการณ์ใดที่ 5% เป็นเกณฑ์คลาสสิกของการรั่วทั่วร่าง เพราะสารสื่อจากแผลขนาดนี้มีน้อยเกินกว่าจะกระทบ endothelium ทั้งระบบ",
  "C":"คำว่า only above 80% ทำให้ผู้ป่วยแผล 30–70% ซึ่งบวมทั้งตัวและเกิด burn shock ให้เห็นเป็นประจำอธิบายไม่ได้ · ไม่มีสถานการณ์ใดที่การรั่วทั่วร่างเริ่มเฉพาะแผลเกิน 80% เพราะทั้งการทดลองและภาพทางคลินิกแสดงการบวมทั่วร่างตั้งแต่แผลราวหนึ่งในสี่ของร่างกาย",
  "D":"50% คือขนาดแผลที่อัตราตายเพิ่มชัดและมักต้องใช้สารน้ำปริมาณมหาศาล แต่การรั่วทั่วร่างเริ่มก่อนหน้านั้นนาน · ไม่มีสถานการณ์ใดที่ 50% เป็นเกณฑ์คลาสสิกของ Arturson เพราะงานนั้นพบการรั่วในเนื้อเยื่อปกติตั้งแต่แผลเกิน 25% ซึ่งเป็นครึ่งหนึ่งของตัวเลขนี้"},
 trap="ตัวเลข 10% และ 15–20% ปรากฏบ่อยในเกณฑ์ burn เช่น ให้น้ำทางหลอดเลือด รับไว้ หรือส่งต่อ จึงชวนสับสน — เกณฑ์ “รั่วทั่วร่าง” ของ Arturson คือ 25% ให้จำแยกว่าเป็นตัวเลขทางพยาธิสรีรวิทยา ไม่ใช่เกณฑ์การรักษา",
 summary=["Arturson 1979: แผลเกิน 25% TBSA → capillary permeability เพิ่มทั้งผิวที่ไหม้และผิวปกติทั่วร่าง",
  "ต่ำกว่า 25%: รั่วและบวมเฉพาะบริเวณแผล · เกิน 25%: hypovolemia + บวมทั่วร่าง",
  "ลายมือหน้า 11: หนูที่ burn ≥ 25% ซึมแล้วตาย · &lt; 25% ซึมแล้วค่อย ๆ หาย",
  "Baxter (ชีทหน้า 5): แผลเกิน 30% → cell transmembrane potential ลด Na ในเซลล์เพิ่ม เซลล์บวมทั้งผิวที่ไหม้และผิวปกติ",
  "ตัวเลขการรักษาที่ต่างกัน: เริ่ม IV resuscitation ผู้ใหญ่ราว 15–20% · เด็กราว 10%",
  "การบวมสูงสุด (ชีทหน้า 5): 8–12 ชั่วโมงในแผลรุนแรงปานกลาง · 12–24 ชั่วโมงในแผลรุนแรงมาก"],
 opinion="เห็นด้วยกับคำตอบ E ความมั่นใจสูง — ทั้งสไลด์หน้า 11 และชีทหน้า 5 ให้เกิน 25% ตรงกัน · จุดที่ควรรู้: ตัวเลขมาจากสัตว์ทดลอง ในคนเกณฑ์ไม่ได้คมชัดที่ 25% พอดี ตำราปัจจุบันกล่าวว่าการตอบสนองทั่วร่างเกิดเมื่อแผลราว 20–30% · ลายมือเขียน ≥ 25% ขณะที่ตัวพิมพ์เขียน &gt;25% ต่างกันเล็กน้อยแต่ไม่มีผลต่อคำตอบ · อย่าใช้ 25% เป็นเกณฑ์เริ่มให้น้ำ เพราะแนวปัจจุบันเริ่ม IV resuscitation ในผู้ใหญ่ที่ราว 15–20% และเด็กราว 10%",
 mnemonic="<b>“หนึ่งในสี่ของตัว = รั่วทั้งตัว”</b>",
 guide="Arturson G (Acta Physiol Scand Suppl 1979;463:111–122); Herndon DN. Total Burn Care 5th ed. (2018) — Pathophysiology of burn shock; ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021)",
 variants=["เด็ก 3 ขวบแผลน้ำร้อนลวก 12% → ยังไม่ถึงเกณฑ์รั่วทั่วร่าง แต่เกินเกณฑ์ให้สารน้ำทางหลอดเลือดในเด็กราว 10% จึงให้ IV ตามสูตรร่วมกับ maintenance ที่มี dextrose",
  "ชายแผล 60% ได้น้ำตามสูตรแต่ hematocrit ยังสูงขึ้นใน 6 ชั่วโมงแรก → เลือดข้นจากพลาสมารั่วออกทั่วร่าง ปรับอัตราสารน้ำตาม urine output",
  "หญิงแผล 30% ที่ลำตัวมีหนังตาบวมในวันแรกทั้งที่หน้าไม่ไหม้ → เป็นการรั่วทั่วร่างตามคาด แต่ยังต้องประเมินทางเดินหายใจซ้ำเป็นระยะ"])

mk(Q, 20, [11, 12, 's5'],
 stem="A 33-year-old woman with 50% TBSA flame burns is hypotensive and oliguric 6 hours after injury. She has no other injuries and no blood loss. Which sequence best explains her organ dysfunction?",
 opts=["Pulmonary embolism → right heart failure → obstructive shock",
       "Capillary leak → hypovolemia → low cardiac output → hypoperfusion",
       "Adrenal crisis → hyponatremia and hyperkalemia → shock",
       "Burn wound sepsis → vasodilation → warm shock with high cardiac output",
       "Occult hemorrhage → anemia → high-output cardiac failure"],
 interp="แผลไหม้ 50% ชั่วโมงที่ 6 ความดันต่ำ ปัสสาวะน้อย ไม่มีบาดเจ็บอื่นและไม่เสียเลือด → ถามลำดับกลไกที่ทำให้อวัยวะทำงานล้มเหลว ต้องใช้หลัก burn shock: การรั่วของ capillary ทั่วร่างนำไปสู่ hypovolemia",
 why="แผล 50% เกินเกณฑ์ 25% จึงเกิด<b>capillary leak ทั่วร่าง</b> พลาสมาและโปรตีนออกจากหลอดเลือดสู่ interstitium อย่างรวดเร็วตั้งแต่ทันทีหลังไหม้ (third space loss) → <b>ปริมาตรในหลอดเลือดลด (hypovolemia)</b> เลือดข้น hematocrit สูงขึ้น → preload ลด → <b>cardiac output ลด</b> ร่วมกับ SVR สูงจาก catecholamine และ myocardial depression ช่วงแรก → <b>เนื้อเยื่อขาดเลือด (inadequate tissue perfusion)</b> → ไตเป็นอวัยวะแรกที่เห็นผล ปัสสาวะน้อย ถ้าไม่แก้จะเป็น ATN และ multiorgan failure · นี่คือ<b>burn shock</b> ซึ่งเป็นชนิด hypovolemic เป็นหลัก ไม่ใช่การติดเชื้อ แม้กลไก cytokine คล้าย septic shock · การรักษาคือให้ crystalloid ตามสูตรแล้ว<b>ปรับอัตราตาม urine output</b> (ผู้ใหญ่ราว 0.5 mL/kg/hr หรือ 30–50 mL/hr) ไม่ใช้ยาขับปัสสาวะ · สไลด์หน้า 12 ลายมือเรียกภาวะนี้ว่า <b>“3<sup>rd</sup> space loss”</b> <b>“= hypovolumic shock”</b> · ชีทหน้า 5 <b>“กลไกนี้จะทำให้เกิดภาวะขาดสารละลายในเส้นเลือด(hypovolemia)”</b> · สไลด์หน้า 11 ลายมือ <b>“= CO ↓ ⟶ inadequate tissue perfusion”</b> และ <b>“↓ organ failure”</b>",
 wrong={
  "A":"PE ทำให้หัวใจขวาวายเฉียบพลันและ obstructive shock มีหอบเหนื่อยเฉียบพลัน JVP สูง ventricle ขวาโต — burn เพิ่มความเสี่ยง VTE จากการนอนนานและภาวะเลือดแข็งตัวง่าย แต่มักเกิดหลังหลายวัน ไม่ใช่ชั่วโมงที่ 6 · จะถูกถ้าผู้ป่วยไฟไหม้ 30% นอนโรงพยาบาลวันที่ 12 หอบเหนื่อยเฉียบพลัน ความดันตก JVP สูง และ echocardiogram เห็นหัวใจห้องขวาโต",
  "C":"Adrenal crisis ช็อกไม่ตอบสนองต่อสารน้ำ Na ต่ำ และ K สูงเฉพาะเมื่อเป็น primary adrenal insufficiency — ไม่ใช่ภาพของชั่วโมงที่ 6 ในผู้ที่ไม่มีโรคต่อมหมวกไตเดิม · จะถูกถ้าหญิงที่เป็น Addison's disease หยุดยา hydrocortisone เองแล้วมาด้วยอาเจียน ช็อกไม่ตอบสนองต่อสารน้ำ Na ต่ำ และ K สูง",
  "D":"Burn wound sepsis เกิดเมื่อเชื้อบุกรุกเนื้อเยื่อใต้แผล มักหลังวันที่ 5–7 ให้ภาพ warm shock หลอดเลือดขยาย cardiac output สูง — ช่วง 6 ชั่วโมงแรกแผลยังไม่ติดเชื้อ และ burn shock ระยะแรก cardiac output ต่ำ · จะถูกถ้าผู้ป่วยไฟไหม้ 45% วันที่ 9 มีไข้สูง แผลเปลี่ยนเป็นสีดำคล้ำ เกล็ดเลือดลด มือเท้าอุ่นแต่ความดันตก",
  "E":"High-output failure จากซีดต้องเป็นภาวะซีดรุนแรงเรื้อรังที่หัวใจบีบแรงเพื่อชดเชย ไม่ใช่ภาพเฉียบพลันใน 6 ชั่วโมงที่ไม่มีเสียเลือด — ช่วงแรกของ burn เลือดกลับข้นขึ้นด้วยซ้ำ · จะถูกถ้าชายที่เลือดออกทางเดินอาหารเรื้อรังหลายเดือนจน Hb 4 g/dL มาด้วยหอบเหนื่อย บวม ชีพจรแรงเร็ว และ cardiac output สูง"},
 trap="ลายมือเปรียบว่า “~ septic shock” และช้อย D ใส่คำว่า sepsis จึงชวนให้เลือก — แต่ใน 6 ชั่วโมงแรกแผลยังไม่ติดเชื้อ ความคล้ายอยู่ที่กลไก cytokine ส่วนชนิดช็อกคือ hypovolemic: เลือดข้น cardiac output ต่ำ และตอบสนองต่อสารน้ำ",
 summary=["Burn shock: capillary leak → hypovolemia → cardiac output ลด → tissue perfusion ไม่พอ → organ failure",
  "ลายมือหน้า 12: ผู้ป่วยตายจากการเสียน้ำออกนอกหลอดเลือด (3rd space loss) = hypovolemic shock สัมพันธ์กับ %burn ราว 20–25%",
  "ระยะแรก 24–48 ชั่วโมง: cardiac output ต่ำ SVR สูง เลือดข้น · ระยะหลัง: hyperdynamic และ hypermetabolic",
  "ตัวติดตามหลัก: urine output ผู้ใหญ่ราว 0.5 mL/kg/hr หรือ 30–50 mL/hr · ปัสสาวะน้อย → เพิ่มอัตราสารน้ำ ไม่ให้ยาขับปัสสาวะ",
  "ปล่อย oliguria นาน → prerenal กลายเป็น ATN",
  "แยกจากช็อกอื่น: sepsis มักหลังวันที่ 5–7 · PE หลังนอนนาน · adrenal crisis ไม่ตอบสนองต่อน้ำ · ช็อกเร็วตั้งแต่ชั่วโมงแรก → หาเลือดออกจากบาดเจ็บร่วม"],
 opinion="เห็นด้วยกับคำตอบ B ความมั่นใจสูง — ลายมือสไลด์หน้า 11 เขียนลำดับตรงตัวว่ารั่ว → CO ↓ → inadequate tissue perfusion → organ failure และชีทหน้า 5 ระบุว่ากลไกนี้ทำให้เกิด hypovolemia · ตำราปัจจุบันมองว่า burn shock มีหลายองค์ประกอบ: hypovolemic เป็นหลัก ร่วมกับ distributive จากสารสื่อ และ cardiogenic จาก myocardial depression ช่วงแรก · ข้อควรระวังตามแนว ABA ปัจจุบัน: ปรับน้ำตามเป้าปัสสาวะ อย่าไล่ให้เกินเป้าจนเกิด fluid creep",
 mnemonic="<b>“รั่ว → พร่อง → บีบน้อย → เลี้ยงไม่พอ → ล้ม”</b>",
 guide="Pham TN, Cancio LC, Gibran NS. American Burn Association practice guidelines burn shock resuscitation (J Burn Care Res 2008;29:257–266); American Burn Association. Advanced Burn Life Support Provider Manual (2018 update); Herndon DN. Total Burn Care 5th ed. (2018) — Pathophysiology of burn shock",
 variants=["ผู้ป่วยไฟไหม้ 40% ชั่วโมงที่ 3 ปัสสาวะ 10 mL/hr → ไม่ให้ furosemide เพราะปัสสาวะน้อยสะท้อนปริมาตรไม่พอ ให้เพิ่มอัตราสารน้ำแล้วประเมินซ้ำทุกชั่วโมง",
  "ผู้ป่วยไฟไหม้ 35% ร่วมกับตกจากที่สูง ความดันต่ำตั้งแต่ชั่วโมงแรกและไม่ตอบสนองต่อสารน้ำ → burn shock ไม่เกิดเร็วขนาดนี้ ให้หาเลือดออกจากการบาดเจ็บร่วมด้วย FAST",
  "ผู้ป่วยไฟไหม้ในห้องปิด 30% lactate สูงมากและ acidosis ไม่ดีขึ้นแม้ปัสสาวะดี → คิดถึงพิษ cyanide ให้ hydroxocobalamin"])

save(Q, 'parts/fill/l23_r02.json')
